import {LocalWorkspaceApi as WorkspaceApi, context, today, townships, mmk, tokenFrom} from './local-api.mjs';

const api=new WorkspaceApi(), root=document.querySelector('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(label,name,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const choice=(label,name,items,value)=>`<label>${esc(label)}<select name="${name}">${items.map(i=>{const v=typeof i==='string'?i:i.value,l=typeof i==='string'?i:i.label;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;
const note=(label,name,value='')=>`<label>${esc(label)}<textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;
const check=(label,name,checked=false)=>`<label class="inline-check"><input name="${name}" type="checkbox" ${checked?'checked':''}>${esc(label)}</label>`;
const button=(label,action,id='',green=false)=>`<button type="button" class="btn ${green?'green':''}" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
const submit=(label)=>`<button type="submit" class="btn green">${esc(label)}</button>`;
const json=body=>({method:'POST',body});
const money=value=>value==null?'Unknown':`${BigInt(value).toLocaleString()} MMK`;
let page='',generation=0,locked=false,orders=[],riders=[],routes=[],queue=[],current=null,requests=[],buyerCard=null,buyerDetails=null,linkURL='',notice='',undoTimer=null;
let eventHistory=[],historyError='';
let buyerBase=location.protocol==='http:'?location.origin:'http://127.0.0.1:8000';
const baseFor=side=>api.connections[side]?.baseUrl||(side==='rider'?location.origin:(location.protocol==='http:'?location.origin:'http://127.0.0.1:8000'));

// Theme helpers share the same native orders, routes and delivery actions.
function icon(name){
  const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',box:'m3 7 9-4 9 4-9 4Zm0 0v10l9 4 9-4V7M12 11v10M7 5l9 4',route:'M6 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm12 16a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM6 7v6a3 3 0 0 0 3 3h6a3 3 0 0 0 3-3V9',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm13 10v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-6-6 6 6-6 6',refresh:'M20 7v5h-5M4 17v-5h5M5.5 7a8 8 0 0 1 13-2L20 7M4 17l1.5 2a8 8 0 0 0 13-2',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',check:'m5 12 4 4L19 6',card:'M3 5h18v14H3ZM3 10h18M7 15h3',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7Zm-4 9 3 3 5-6',logout:'M9 4H4v16h5m5-13 5 5-5 5M9 12h12'};
  return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
}
const brand=()=>`<a class="lp-brand" href="#/admin"><span class="lp-brand-mark">${icon('box')}</span><span>LannPya<span class="brand-caption">DELIVERY, CONNECTED.</span></span></a>`;
const dateLabel=value=>{if(!value)return 'To be arranged';const d=new Date(value+'T00:00:00+06:30');return Number.isNaN(d.getTime())?esc(value):new Intl.DateTimeFormat('en',{timeZone:'Asia/Rangoon',weekday:'long',month:'short',day:'numeric'}).format(d);};
function windowLabel(value){if(!value)return 'Any time';if(!value.includes('/'))return esc(value);const [start,end]=value.split('/').map(v=>new Date(v));if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime()))return esc(value);const date=new Intl.DateTimeFormat('en',{timeZone:'Asia/Rangoon',weekday:'long',month:'long',day:'numeric'}).format(start),time=new Intl.DateTimeFormat('en',{timeZone:'Asia/Rangoon',hour:'numeric',minute:'2-digit'});return `${esc(date)}<span class="window-range">${esc(time.format(start))} – ${esc(time.format(end))}</span>`;}
const statusLabel=value=>({DRAFT:'Draft',NEEDS_REVIEW:'Needs review',AWAITING_CONFIRMATION:'Awaiting confirmation',CONFIRMED:'Confirmed',READY_FOR_DISPATCH:'Ready to dispatch',ASSIGNED:'Assigned',OUT_FOR_DELIVERY:'Out for delivery',DELIVERED:'Delivered',FAILED:'Delivery unsuccessful',CANCELLED:'Cancelled',REVIEW_REQUIRED:'Review required',APPROVE:'Approved',REJECT:'Declined',APPLIED:'Saved'}[value]||String(value||'Not set').replaceAll('_',' '));
const statusPill=value=>`<span class="status-pill status-${esc(String(value).toLowerCase())}"><span class="status-dot"></span>${esc(statusLabel(value))}</span>`;
function courierArt(){return `<svg class="courier-art" viewBox="0 0 130 140" fill="none" aria-hidden="true"><circle cx="61" cy="25" r="11" stroke="currentColor" stroke-width="1.5"/><path d="M49 24c-9 1-10-7-4-10 0-10 13-14 19-6 10-1 16 11 9 17M49 40c-16 8-19 30-8 41l34-8-6-28-20-5ZM44 79l-9 30 20 20 8-7-13-17 11-21m3-8 18 23-5 26 10 1 11-32-23-28M37 59 19 50l-6 8 26 19m29-30 15 5M87 47h33v33H87Zm16 0v33M93 124h14M51 131h15" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="m42 68 34-7 3 17-39 7Z" fill="currentColor"/><path d="M99 40v-8m-6 8-4-5m15 5 5-5" stroke="currentColor" stroke-width="1.3"/></svg>`;}
function progress(status){const step=status==='DELIVERED'?3:status==='OUT_FOR_DELIVERY'?2:['CONFIRMED','READY_FOR_DISPATCH','ASSIGNED'].includes(status)?1:0;return `<ol class="delivery-progress" aria-label="Delivery progress">${['Order received','Confirmed','Out for delivery','Delivered'].map((label,i)=>`<li class="${i<=step?'is-reached':''} ${i===step?'is-current':''}" ${i===step?'aria-current="step"':''}><span class="progress-node">${i<step?icon('check'):''}</span><span>${label}</span></li>`).join('')}</ol>`;}
function customerHero(status='DRAFT'){
  const title=status==='DELIVERED'?'Your parcel has<br>arrived.':status==='OUT_FOR_DELIVERY'?'A little closer<br>to your doorstep.':['CONFIRMED','READY_FOR_DISPATCH','ASSIGNED'].includes(status)?'Your order is<br>confirmed.':status==='CANCELLED'?'Delivery<br>cancelled.':status==='FAILED'?'We couldn’t<br>reach you.':'Your delivery,<br>made simple.';
  return `<section class="customer-hero"><span class="section-eyebrow">LANNPYA · YOUR DELIVERY</span><div class="customer-hero-row"><div><h1>${title}</h1><p>${status==='DELIVERED'?'Delivered with care. Thank you for choosing LannPya.':status==='OUT_FOR_DELIVERY'?'Your rider is on the way. Keep your phone nearby.':'A few small details. A smoother delivery.'}</p></div>${courierArt()}</div></section>`;
}
function routeMap(label,area='Yangon'){
  return `<section class="route-map" aria-label="Illustrative route overview, not live navigation"><div class="map-grid" aria-hidden="true"><div class="map-river"></div><div class="map-park park-one"></div><div class="map-park park-two"></div><svg class="map-streets" viewBox="0 0 480 300" preserveAspectRatio="none"><path d="M-20 250 510 30M-20 40 490 235M90-20 160 330M300-20 340 330M-20 160 510 155" stroke="#fff" stroke-width="13" fill="none"/><path d="M-20 250 510 30M-20 40 490 235" stroke="#eadbae" stroke-width="5" fill="none"/><path d="M140 238v-48l44-21h67l24-36h75" stroke="#fff" stroke-width="9" fill="none" stroke-linejoin="round"/><path d="M140 238v-48l44-21h67l24-36h75" stroke="#172c3a" stroke-width="5" fill="none" stroke-linejoin="round"/><circle cx="140" cy="238" r="8" fill="#1a51e8" stroke="white" stroke-width="4"/><circle cx="350" cy="133" r="7" fill="#172c3a" stroke="white" stroke-width="3"/></svg></div><span class="map-town">${esc(area)}</span><span class="map-layer-icon">${icon('route')}</span><div class="map-destination">${icon('pin')}<div><strong>${esc(label||'Your next delivery')}</strong><span>Schematic overview · not live GPS</span></div></div><span class="map-disclaimer">Illustrative layout · use Google Maps for navigation</span></section>`;
}
function dashboardHero(){const review=orders.filter(o=>['DRAFT','NEEDS_REVIEW','AWAITING_CONFIRMATION'].includes(o.status)).length,delivered=orders.filter(o=>o.status==='DELIVERED').length,active=routes.filter(r=>r.state==='dispatched').length;return `<div class="dashboard-heading"><div><span class="section-eyebrow">YOUR OPERATIONS, AT A GLANCE</span><h1>Home</h1><p>A clear view. A smoother delivery day.</p></div><span class="date-chip">${icon('clock')}${dateLabel(today())}</span></div><section class="dashboard-balance"><div><span>Total parcels</span><strong>${orders.length.toLocaleString()}</strong><small>${delivered} delivered · ${review} awaiting review</small></div><div class="balance-aside">${icon('box')}<span>Every parcel.<br>One connected workspace.</span></div></section><nav class="quick-actions" aria-label="Dispatcher shortcuts"><a href="#add-order" data-section="add-order">${icon('plus')}<span>Add order</span></a><a href="#order-board" data-section="order-board">${icon('box')}<span>View orders</span></a><a href="#route-planner" data-section="route-planner">${icon('route')}<span>Plan a route</span></a><a href="#hub-closeout" data-section="hub-closeout">${icon('card')}<span>Hub closeout</span></a></nav><div class="dashboard-statline"><span><i class="legend-blue"></i>${active} active routes</span><span>${riders.length} rider profiles</span><span>From your saved records</span></div>`;}

function message(text,error=false){const el=document.querySelector('#api-status');el.className=error?'error':'success';el.textContent=text;el.hidden=false;}
function errorText(error){
  if(['TimeoutError','AbortError'].includes(error.name))return 'The API request timed out. Its outcome may be unknown; refresh before retrying to avoid recording the same operation twice.';
  if(error.name==='TypeError')return 'Cannot reach the API. Check the backend address/CORS and reconnect. No success was confirmed; refresh before retrying because the server may have processed the request.';
  const detail=error.details?.map(d=>`${d.location?.join('.')}: ${d.message}`).join('\n');
  return `${error.message}${detail?'\n'+detail:''}${error.status===409?'\nRefresh to review the latest state before retrying.':''}${error.status===429?`\nWait ${error.retryAfter||60} seconds before trying again.`:''}`;
}
function shell(body,loading=false){
  globalThis.LannPyaCustomerMap?.destroy();
  const side=page==='customer'||page.startsWith('track/')?'customer':page==='rider'?'rider':'admin';
  for(const role of ['admin','customer','rider'])document.body.classList.toggle('role-'+role,side===role);
  document.body.classList.add('api-workspace');
  const roleLinks=`<nav class="role-switch" aria-label="Choose workspace">${[['admin','Admin'],['customer','Customer'],['rider','Rider']].map(([key,label])=>`<a href="#/${key}" ${side===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
  const sideNav=side==='admin'?`<aside class="api-sidebar">${brand()}<span class="sidebar-label">WORKSPACE</span><nav class="side-menu" aria-label="Admin navigation"><a href="#/admin" aria-current="page">${icon('home')}<span>Home</span></a><a href="#/admin" data-section="order-board">${icon('box')}<span>Orders</span></a><a href="#/admin" data-section="route-planner">${icon('route')}<span>Routes</span></a><a href="#/admin" data-section="hub-closeout">${icon('card')}<span>Hub closeout</span></a><a href="#/admin" data-section="rider-profiles">${icon('users')}<span>Riders</span></a></nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('shield')}<strong>A little more clarity.</strong><span>Orders, riders and deliveries.<br>Working better together.</span></div><a class="sidebar-account" href="#/admin"><span class="account-avatar">LP</span><span>${esc(api.connections.admin?.actor.name||'Admin workspace')}<small>Local API workspace</small></span></a><a class="prototype-link" href="prototype.html">Open local prototype ${icon('arrow')}</a></div></aside>`:'';
  root.innerHTML=`<div class="api-frame">${sideNav}<div class="api-surface"><header class="api-header">${side==='admin'?'<span class="workspace-crumb">Workspace <span>/</span> '+(page.startsWith('order/')?'Order details':'Overview')+'</span>':brand()}${roleLinks}<span class="connection-indicator"><i></i>LOCAL BACKEND ? AI MOCK</span></header><main class="api-main" id="workspace-top"><p id="api-status" role="status" aria-live="polite" hidden></p>${body}<details class="workspace-disclosure"><summary>${icon('shield')}About this workspace</summary><p>Local API integration · SQLite database · exactly three sides. No production login, real AI or trusted map verification. API records are separate from your untouched browser prototype.</p></details></main>${side==='rider'?`<nav class="rider-bottom-nav" aria-label="Rider sections"><a href="#/rider" data-section="workspace-top">${icon('route')}<span>My route</span></a><a href="#/rider" data-section="delivery-stops">${icon('box')}<span>Stops</span></a><a href="#/rider" data-section="rider-handover">${icon('card')}<span>Handover</span></a><a href="#/rider" data-section="rider-account">${icon('users')}<span>Account</span></a></nav>`:''}</div></div>`;
  if(notice&&!loading){message(notice);notice='';}
  wire();
  globalThis.LannPyaCustomerMap?.mount(document.querySelector('#buyer-location-form'));
}
function connection(side){
  return `<div class="connection-heading"><span class="section-eyebrow">LOCAL TEST INTEGRATION</span><h1>${side==='rider'?'Ready for your route?':'Welcome to your workspace.'}</h1><p>Real backend storage. Mock AI. Development identities only.</p></div><form id="connect-form" class="panel connection-card" data-side="${side}">${field('Local origin','base',location.origin,'url','readonly')}${side==='rider'?field('Rider ID (blank selects the first local rider)','actor_id'):''}${submit('Enter local '+side+' workspace')}<p>No private access token is delivered to this browser. This is a local developer boundary, not production login.</p></form>`;
}

function manualForm(){return `<section class="panel"><h2>Add an order</h2><details><summary>Parse a pasted address first (optional)</summary><form id="parse-form">${note('Chat order text','raw')}${submit('Parse with backend rules')}<button type="button" class="btn" data-action="save-raw">Save original chat order</button><p class="small">Fill parcel description and delivery day below first. This preserves original text and extraction provenance; correct saved fields afterward.</p></form><pre id="parse-result" class="small"></pre></details><form id="create-form"><div class="form-grid">${field('Recipient','customer_name','','text','required')}${field('Phone','customer_phone','','tel','required')}${field('Parcel description','item','','text','required')}${field('Invoice/reference','reference')}${field('Sender (optional)','sender')}${choice('Township','township',townships,'Kamayut')}${field('Street','street')}${field('Landmark','landmark')}${field('Floor/unit','floor')}${choice('Payment','payment',['cod','prepaid'],'cod')}${field('Expected COD (MMK)','cod_amount','','number','min="0" max="1000000000" step="1" required')}${field('Delivery day · Yangon','delivery_day',today(),'date','required')}</div><p>Availability defaults to Any time. Specific customer rescheduling is reviewed under the backend courier policy.</p>${note('Instructions','delivery_instructions')}<details><summary>Known delivery coordinates (optional)</summary><div class="form-grid">${field('Latitude','latitude','','number','step="0.0000001"')}${field('Longitude','longitude','','number','step="0.0000001"')}</div><p class="small">Manual coordinates do not prove map accuracy. Leave blank for customer submission and admin review.</p></details>${check('Parcel has physically arrived at the hub','hub_received')}${submit('Create order')}</form></section>`;}
function routeCard(route,side){
  const h=route.handover,complete=route.items.every(o=>o.status==='DELIVERED'||o.status==='FAILED'&&o.return_received);
  let actions='';
  if(side==='admin'){
    if(route.state==='draft'&&route.items.length)actions=route.day===today()?button('Dispatch route','dispatch',route.id,true):`<p class="notice">Departure is scheduled for ${dateLabel(route.day)} (Yangon), not today.</p>`;
    if(h&&route.state!=='closed')actions=h.status!=='received'?button('Receive cash & close route','receipt',route.id,true):button('Close route','close-route',route.id,true);
  }else if(complete&&route.items.length&&['dispatched','closing'].includes(route.state)&&h?.status!=='received'){
    actions=h?button('Update handover amount','different',route.id):button(`Hand over ${money(route.recorded_total)}`,'handover',route.id,true)+button('Different amount','different',route.id);
  }
  return `<section class="panel route-card"><div class="route-card-top"><h2>Route ${esc(route.id.slice(0,8))}</h2>${statusPill(route.state)}</div><p class="route-meta"><span>${dateLabel(route.day)}</span><span>${icon('users')} ${esc(riders.find(r=>r.id===route.rider_id)?.name||(api.connections.rider?.actor.id===route.rider_id?api.connections.rider.actor.name:route.rider_id))}</span><span>${route.items.length} parcels</span></p>${route.items.map(o=>`<div class="order-row">${side==='admin'?`<a href="#/order/${o.id}">${esc(o.name||o.id)}</a>`:`<strong>${esc(o.name||o.id)}</strong>`}${o.return_received?'<span class="status-pill status-delivered">Returned to hub</span>':statusPill(o.status)}<span>${o.collection?money(o.collection.actual):''}</span>${side==='admin'&&o.status==='FAILED'&&!o.return_received?button('Receive physical return','return',o.id):''}</div>`).join('')||'<p class="small">No parcels assigned yet.</p>'}<div class="route-total"><span>Recorded cash</span><strong>${money(route.recorded_total)}</strong></div>${h?`<p class="small">Handover: ${esc(h.status)} · Rider declared ${money(h.declared)}${h.received!=null?` · Hub received ${money(h.received)}`:''}</p>`:''}${route.state==='closing'&&route.blockers.length?`<p class="notice">Still open: ${route.blockers.map(esc).join('; ')}</p>`:''}<div class="action-row">${actions}</div></section>`;
}
function requestCard(r){const values=r.submitted_values||{},reasons={INITIAL_PIN_REQUIRES_REVIEW:'This delivery point needs your review.',TOWNSHIP_BOUNDARY_UNVERIFIED:'Map boundaries have not been independently verified.',PENDING_BUYER_REVIEW:'Another customer update is awaiting review.'};return `<article class="request-card"><div class="request-card-heading"><span class="request-symbol">${icon(r.kind==='LOCATION'?'pin':'clock')}</span><div><h3>${r.kind==='LOCATION'?'Delivery point update':'Delivery preference update'}</h3>${statusPill(r.resolution||r.decision)}</div></div>${values.latitude!=null?`<p class="request-summary">Latitude ${esc(values.latitude)}<br>Longitude ${esc(values.longitude)}</p>`:`<p class="request-summary">${esc(statusLabel(values.action||r.kind))}${values.instructions?'<br>'+esc(values.instructions):''}</p>`}<p class="small">${r.reason_codes.map(code=>esc(reasons[code]||String(code).toLowerCase().replaceAll('_',' '))).join(' ')}</p>${r.decision==='REVIEW_REQUIRED'&&!r.resolution?button('Review request','review',r.id):''}<details><summary>Submission details</summary><pre>${esc(JSON.stringify(r.submitted_values,null,2))}</pre></details></article>`;}
function adminNextLabel(order){
  const p=context(order);
  if(order.status==='ASSIGNED')return 'Confirm departure';
  if(order.status==='OUT_FOR_DELIVERY')return 'View rider progress';
  if(order.status==='FAILED')return p.return_received_at?'Review route closeout':'Receive physical return';
  if(order.status==='DELIVERED')return routes.find(r=>r.id===p.route_id)?.state==='closed'?'View completed delivery':'Cash & closeout';
  return order.status==='CANCELLED'?'View record':'Review & assign';
}
function adminView(){return `${dashboardHero()}<section class="panel board-panel" id="order-board"><div class="section-heading"><div><h2>Orders</h2><p>Every parcel, from intake to doorstep.</p></div>${button('Refresh','refresh')}</div><div class="board-tabs"><strong>All parcels</strong><span>${orders.filter(o=>o.status==='OUT_FOR_DELIVERY').length} on the road</span><span>${orders.filter(o=>o.status==='DELIVERED').length} delivered</span></div>${orders.length?`<div class="table-scroll"><table class="order-table"><thead><tr><th>Parcel / recipient</th><th>Status</th><th>At the hub</th><th>COD amount</th></tr></thead><tbody>${orders.map(o=>`<tr><td><a class="order-cell" href="#/order/${o.id}"><span class="parcel-avatar">${icon('box')}</span><span><strong>${esc(o.customer_name||'Review recipient')}</strong><small>${esc(context(o).item||'Parcel')} · ${esc(o.township||'Address needs review')}</small></span></a></td><td>${statusPill(o.status)}<small class="small">${esc(o.confidence_level)} address confidence</small><a class="order-next-link" href="#/order/${o.id}">${esc(adminNextLabel(o))} →</a></td><td><span class="small">${context(o).hub_received_at?'Received':'Awaiting receipt'}</span></td><td>${money(o.cod_amount)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">${icon('box')}<strong>A fresh start for your next delivery.</strong><p>No API orders yet. Browser-prototype records are not automatically imported.</p><a href="#add-order" data-section="add-order">Add your first parcel →</a></div>`}</section><div id="add-order" class="admin-form-section">${manualForm()}</div><div class="dashboard-two-col"><section class="panel" id="route-planner"><span class="section-eyebrow">PLAN THE DAY</span><h2>Create a route</h2><form id="new-route-form">${choice('Rider','rider_id',riders.map(r=>({value:r.id,label:r.name})),riders[0]?.id)}${field('Delivery day','day',today(),'date','required')}${submit('Create draft route')}</form></section><section class="panel" id="rider-profiles"><span class="section-eyebrow">YOUR DELIVERY TEAM</span><h2>Add a rider</h2><form id="new-rider-form">${field('Rider name','name','','text','required')}${submit('Add available rider')}</form><details><summary>About rider access</summary><p class="small">The starter creates two riders and their separate API instances. New profiles are selectable by ID through the local server-side role boundary; private tokens never enter this page.</p></details></section></div><section id="hub-closeout"><div class="section-heading"><div><h2>Routes & handovers</h2><p>A complete picture, right down to the last parcel.</p></div><span>${routes.length} routes</span></div>${routes.map(r=>routeCard(r,'admin')).join('')||`<div class="empty-state">${icon('route')}<strong>Your routes will appear here.</strong><p>Choose a rider and delivery day to get started.</p></div>`}</section><div class="small">Connected as ${esc(api.connections.admin.actor.name)} · ${button('Disconnect','disconnect','admin')}</div>`;}
function preparationCard(p,editable){
  if(!editable)return '';
  const pending=requests.filter(r=>r.decision==='REVIEW_REQUIRED'&&!r.resolution);
  const checks=[
    [!!p.delivery_day&&p.delivery_day>=today(),'Delivery day is today or later'],
    [!pending.length,pending.length?pending.length+' customer update(s) need review':'Customer updates reviewed'],
    [current.latitude!=null&&current.longitude!=null,'Delivery point saved'],
    [current.confidence_level!=='RED'&&!!current.customer_phone&&!!current.township&&current.cod_amount!=null,'Contact, address and amount checked'],
    [!p.incident,'No open parcel incident']
  ];
  const blocked=checks.some(([ok])=>!ok);
  const choices=[
    ...routes.filter(r=>r.state==='draft'&&r.day===p.delivery_day&&riders.some(x=>x.id===r.rider_id&&x.operational_status==='AVAILABLE')).map(r=>({value:'route:'+r.id,label:(riders.find(x=>x.id===r.rider_id)?.name||'Rider')+' · existing route '+r.id.slice(0,8)+' · '+r.items.length+' parcel(s)'})),
    ...riders.filter(r=>r.operational_status==='AVAILABLE').map(r=>({value:'rider:'+r.id,label:r.name+' · create a new route'}))
  ];
  return `<section class="panel workflow-next" id="prepare-parcel"><span class="section-eyebrow">NEXT · PREPARE & ASSIGN</span><h2>From reviewed parcel to rider, in one step</h2><p>Delivery ${esc(p.delivery_day||'day not set')}. This uses the saved fields below. Save any edits first.</p><ul class="readiness-list">${checks.map(([ok,label])=>`<li class="${ok?'is-ready':'needs-attention'}"><span aria-hidden="true">${ok?'✓':'!'}</span>${esc(label)}</li>`).join('')}</ul>${blocked?`<p class="notice">Resolve the highlighted checks before assigning. <a href="#review-fields" data-section="review-fields">Review fields</a> or <a href="#customer-requests" data-section="customer-requests">review customer updates</a>.</p>`:`<form id="prepare-assignment-form">${choice('Rider route · '+(p.delivery_day||'set the delivery day'),'selection',choices,choices[0]?.value)}${!p.hub_received_at?check('I have physically received this parcel at the hub','received'):'<p class="small">✓ Physical hub receipt already recorded</p>'}${check('I reviewed this delivery point and accept that map accuracy is not independently verified','ack')}${choices.length?submit('Prepare & assign parcel'):'<p class="notice">No available riders. Add or make a rider available before assigning.</p>'}</form>`}<p class="small">One save completes review, records receipt if explicitly checked, and assigns the parcel. Customer edits freeze when prepared. It does not dispatch the rider.</p></section>`;
}
function historyView(){
  const rows=[...eventHistory].sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at))||String(a.id).localeCompare(String(b.id)));
  return `<section class="panel" id="delivery-history"><h2>Delivery event history</h2><p class="small">Persisted backend events, oldest first. Private metadata and submitted values are excluded.</p>${historyError?`<p class="error" role="alert">${esc(historyError)}</p>${button('Retry history','refresh')}`:rows.length?`<ol class="event-timeline">${rows.map(e=>`<li data-event-type="${esc(e.event_type)}"><strong>${esc(e.event_type.replaceAll('_',' '))}</strong><time datetime="${esc(e.created_at)}">${esc(new Date(e.created_at).toLocaleString('en-GB',{timeZone:'Asia/Rangoon'}))} Yangon</time><span>${esc(statusLabel(e.previous_status))} to ${esc(statusLabel(e.new_status))}</span></li>`).join('')}</ol>`:'<p>No delivery events yet.</p>'}</section>`;
}
function orderView(){
  const p=context(current),editable=['DRAFT','NEEDS_REVIEW','AWAITING_CONFIRMATION','CONFIRMED','READY_FOR_DISPATCH'].includes(current.status),assignedRoute=routes.find(r=>r.id===p.route_id);
  return `<a class="detail-back" href="#/admin">← Back to orders</a><div class="detail-heading"><div><span class="section-eyebrow">PARCEL DETAILS</span><h1>${esc(current.customer_name||'Order')}</h1></div>${statusPill(current.status)}</div><p>${esc(current.id)} · version ${current.version} ${button('Refresh','refresh')}</p>${preparationCard(p,editable)}${assignedRoute?`<div class="section-heading"><div><h2>${assignedRoute.state==='draft'?'Next · confirm departure':'Assigned route'}</h2><p>${assignedRoute.state==='draft'?'Dispatch here when the rider and every parcel on this route are physically ready. This dispatches the whole route.':'Delivery, returns and cash stay together on this route.'}</p></div></div>${routeCard(assignedRoute,'admin')}`:''}<section class="panel"><h2>Parcel and custody</h2><p>${esc(p.item||'Legacy parcel')} · ${money(current.cod_amount)} · Delivery ${esc(p.delivery_day||'Not set')} · ${esc(p.hub_received_at?'At hub':'Not received at hub')}</p>${!p.hub_received_at?button('Parcel physically received','receive',current.id):''}${current.status==='FAILED'&&!p.return_received_at?button('Receive physical return','return',current.id):''}${button(p.incident?'Resolve incident':'Record incident',p.incident?'resolve-incident':'incident',current.id)}${p.collection&&p.collection.actual!==p.collection.expected&&!p.collection.resolution?button('Resolve collection difference','resolve-difference',current.id):''}<p>${p.incident?'Incident: '+esc(p.incident):''}</p>${p.collection?`<p>Expected ${money(p.collection.expected)} · Collected ${money(p.collection.actual)} · ${esc(p.collection.reason)}</p>`:''}</section>${editable?`<section class="panel" id="review-fields"><h2>Review fields</h2><form id="edit-api-form"><div class="form-grid">${field('Recipient','customer_name',current.customer_name)}${field('Phone','customer_phone',current.customer_phone)}${choice('Township','township',townships,current.township)}${field('Street','street',current.street)}${field('Landmark','landmark',current.landmark)}${field('Floor','floor',current.floor)}${field('Expected COD (0 prepaid)','cod_amount',current.cod_amount,'number','min="0" step="1" required')}${field('Latitude','latitude',current.latitude,'number','step="0.0000001"')}${field('Longitude','longitude',current.longitude,'number','step="0.0000001"')}</div>${note('Instructions','delivery_instructions',current.delivery_instructions)}${submit('Save fields & rerun checks')}</form><p class="small">Critical edits may return the order to review; phone changes revoke customer links.</p></section>`:''}<section class="panel" id="customer-requests"><h2>Customer link & updates</h2><p>Generate while the order is under review, before preparing dispatch. Reissuing revokes the previous link.</p>${button('Create / reissue customer link','link',current.id)}${linkURL?`${field('Private customer link','generated-link',linkURL,'text','readonly')}<a href="${esc(linkURL)}" target="_blank" rel="noopener noreferrer">Open customer card</a>`:''}<h3>Customer requests</h3>${requests.map(requestCard).join('')||'<p>No customer requests.</p>'}</section>${['DRAFT','NEEDS_REVIEW','AWAITING_CONFIRMATION','CONFIRMED'].includes(current.status)?`<details class="panel"><summary>Advanced · finish review without choosing a rider yet</summary><form id="ready-form">${check('I reviewed this delivery point and accept that map accuracy is not independently verified','ack')}${submit('Mark ready only')}</form><p class="small">Resolve customer requests first. Preparing also freezes backend customer edits.</p></details>`:''}${current.status==='ASSIGNED'?button('Unassign draft parcel','unassign',current.id):''}${historyView()}`;
}
function riderStage(){
  if(queue.some(o=>o.status==='OUT_FOR_DELIVERY'))return {title:queue.filter(o=>o.status==='OUT_FOR_DELIVERY').length+' delivery stop(s) ahead',text:'Your current stop is below. Save its delivery or return outcome to see what comes next.',target:'delivery-stops'};
  const active=routes.filter(r=>['dispatched','closing'].includes(r.state));
  const returns=active.flatMap(r=>r.items.filter(o=>o.status==='FAILED'&&!o.return_received));
  if(returns.length)return {title:'Return '+returns.length+' parcel(s) to the hub',text:'No delivery stops remain. Give the failed parcels back to admin and ask them to record physical return receipt. Then refresh for cash handover.',target:'rider-handover'};
  if(active.some(r=>r.items.length&&r.items.every(o=>o.status==='DELIVERED'||o.status==='FAILED'&&o.return_received)&&!r.handover))return {title:'Next · hand over your cash',text:'Delivery outcomes are recorded. Review the route total below, then submit one handover. Prepaid routes still need a zero-cash handover.',target:'rider-handover'};
  if(active.some(r=>['submitted','disputed'].includes(r.handover?.status)))return {title:'Waiting for hub cash receipt',text:'Your handover is submitted. Admin must count the physical cash and receive & close the route. Refresh afterwards; do not hand it over twice.',target:'rider-handover'};
  if(active.length)return {title:'Hub review still needed',text:'Review the route issues below. Admin must resolve any cash difference, incident or return before closure.',target:'rider-handover'};
  if(queue.length||routes.some(r=>r.state==='draft'&&r.items.length))return {title:'Waiting for admin departure',text:'These parcels are assigned, but the route has not departed. Ask admin to dispatch the route, then refresh. You cannot deliver a draft route.',target:'delivery-stops'};
  return {title:routes.some(r=>r.state==='closed')?'All routes closed.':'No assigned deliveries yet.',text:'Refresh after admin assigns and dispatches work to this rider.',target:'rider-handover'};
}
function stopCard(o,i){
  return `<section class="panel ${i===0?'current-stop':''}"><div class="rider-stop-heading">${icon('route')}<span>${o.status==='OUT_FOR_DELIVERY'?'Heading to drop-off':'Waiting for departure'} · ${i===0?'Current stop':'Stop '+(i+1)}</span></div><div class="rider-destination"><h2>${esc(o.customer_name||'Recipient')}</h2><p>Drop-off: ${esc([o.street,o.township].filter(Boolean).join(', ')||'Ask admin to confirm the address')}</p><p>${esc(o.building_floor_unit||'')} · ${windowLabel(o.delivery_time_window||'Availability not specified')}</p><p class="stop-landmark">${esc(o.landmark||'Landmark not supplied')}</p></div>${o.delivery_instructions?`<div class="stop-note">${esc(o.delivery_instructions)}</div>`:''}<div class="stop-payment">${icon('card')}<span>${Number(o.cod_amount)===0?'Prepaid · collect no cash':'Cash on delivery'}</span><strong>${money(o.cod_amount)}</strong></div><details><summary>Delivery details</summary><p class="small">Order ${esc(o.order_id)}</p><p class="small">${esc(o.location_verification?.status||'unverified')} map accuracy · Buyer availability ${esc(o.buyer_confirmation?.availability||'not specified')}</p></details><div class="rider-stop-actions">${o.navigation_ready&&o.navigation_url?`<a class="btn" href="${esc(o.navigation_url)}" target="_blank" rel="noopener noreferrer">${icon('arrow')}Open Google Maps</a>`:'<p class="notice">No navigation-ready point. Ask admin to review the delivery location.</p>'}${o.status==='OUT_FOR_DELIVERY'?button('✓ Delivered','deliver',o.order_id,true)+button('Cannot deliver / return','failed',o.order_id):'<p class="small">Assigned but not departed. Wait for admin route dispatch.</p>'}</div></section>`;
}
function riderView(){
  const next=queue[0],stage=riderStage(),openRoutes=routes.filter(r=>r.state!=='closed'),closedRoutes=routes.filter(r=>r.state==='closed');
  return `${routeMap(next?.street||next?.customer_name||'Your next delivery',next?.township||'Yangon')}<section class="rider-overview"><span class="section-eyebrow">YOUR ROUTE, ${esc(api.connections.rider.actor.name.toUpperCase())}</span><h1>${esc(stage.title)}</h1><p>${esc(stage.text)}</p><div class="action-row">${button('Refresh queue','refresh')}<a class="btn green" href="#${stage.target}" data-section="${stage.target}">Go to next action ↓</a></div></section><div id="delivery-stops" class="section-heading"><h2>${queue.length?'Current stop':'Delivery stops'}</h2><span>${queue.length} in your queue</span></div>${next?stopCard(next,0):`<section class="panel empty-state">${icon('check')}<strong>No active delivery stops.</strong><p>${esc(stage.text)}</p></section>`}${queue.length>1?`<details class="panel remaining-stops"><summary>Other assigned stops · ${queue.length-1}</summary>${queue.slice(1).map((o,i)=>stopCard(o,i+1)).join('')}</details>`:''}<div id="rider-handover" class="section-heading"><h2>Returns & cash handover</h2></div>${openRoutes.map(r=>routeCard(r,'rider')).join('')||'<p class="small">No open routes.</p>'}${closedRoutes.length?`<details class="panel"><summary>Completed routes · ${closedRoutes.length}</summary>${closedRoutes.map(r=>routeCard(r,'rider')).join('')}</details>`:''}<section id="rider-account"><div class="rider-account"><span class="account-avatar">${esc(api.connections.rider.actor.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(api.connections.rider.actor.name)}</strong><p>Rider workspace · stop safely before using your phone</p></div></div>${button('Disconnect','disconnect','rider')}<details><summary>Connection & offline information</summary><p class="small">API mode requires a connection for all writes. It never silently saves a delivery only in local storage.</p></details></section>`;
}
function customerView(){
  if(!buyerCard)return `${customerHero()}<form id="open-buyer-form" class="panel"><h2>Your private delivery link</h2><p class="customer-note">Open the link your delivery team shared with you. No app to install, no account to create.</p>${field('Delivery backend','base',buyerBase,'url','required')}${field('Private delivery link/token','link','','text','required autocomplete="off"')}${submit('Open my delivery')}</form><p class="customer-footer">No admin or rider access token is needed.<br>Ask your delivery admin for your order link.</p>`;
  if(buyerCard.state==='VIEW_ONLY')return `${customerHero('DELIVERED')}<section class="panel"><h2>Delivery completed</h2><div class="delivery-track-card">${progress('DELIVERED')}<p class="track-caption">Your parcel’s journey<strong>Delivered to its destination</strong></p></div><p class="customer-order-reference">Order #${esc(buyerCard.order_reference)}</p><p class="customer-note">This delivery is view-only. Contact admin for any corrections.</p></section>`;
  if(buyerCard.state==='LOCKED')return `${customerHero()}<section class="panel"><h2>Link locked</h2><p class="customer-note">Your details are protected. Contact admin for a replacement link.</p></section>`;
  const state=buyerDetails?.status||buyerCard.delivery_status;
  const tracking=`<div class="delivery-track-card">${progress(state)}<p class="track-caption">Delivery status<strong>${esc(statusLabel(state))}</strong></p></div>`;
  if(!buyerDetails)return `${customerHero(state)}${tracking}<form id="verify-api-form" class="panel"><h2>A quick check, just for you</h2><p class="customer-note">Verify your delivery with the last four digits of the recipient’s phone number.</p>${field('Last 4 digits of recipient phone','digits','','text','required pattern="[0-9]{4}" maxlength="4" inputmode="numeric" autocomplete="off"')}${submit('Verify')}</form><p class="customer-order-reference">Order #${esc(buyerCard.order_reference)}</p>`;
  return `${customerHero(state)}<section class="panel"><h2>Delivery availability</h2><p class="delivery-date">${windowLabel(buyerDetails.delivery_time_window)}</p>${tracking}<h2>Delivery address</h2><p class="customer-address">${esc([buyerDetails.street,buyerDetails.township].filter(Boolean).join(', ')||'Let us know where to find you.')}</p><p class="customer-note">${esc(buyerDetails.landmark||'')}</p></section><section class="panel"><form id="buyer-location-form"><h2>Confirm your delivery point</h2><div id="buyer-map" role="region" aria-label="Choose delivery location"></div><p id="map-selection-status" class="small" role="status">Yangon overview only. No delivery pin selected. Click the map or enter coordinates.</p><button type="button" class="btn" id="load-street-tiles">Load street map</button><p class="small">Optional OpenStreetMap tiles contact an external map service and reveal the viewed area, not your phone or order. No tiles load until requested.</p><div class="form-grid">${field('Latitude','latitude',buyerDetails.latitude,'number','step="0.0000001" required')}${field('Longitude','longitude',buyerDetails.longitude,'number','step="0.0000001" required')}</div>${button('Use my current location','gps')}${check('I deliberately selected this delivery point; admin review may be required','initial_pin_acknowledged')}${submit('Submit delivery point')}</form><p class="small">No trusted township boundaries are installed. A saved proposal is not automatically a verified delivery location.</p></section><section class="panel"><form id="buyer-response-form"><h2>Make it your delivery</h2>${choice('How will you receive your parcel?','action',[{value:'AVAILABLE',label:'At home'},{value:'LEAVE_WITH_SECURITY',label:'Leave with security (review may be required)'},{value:'RESCHEDULE',label:'Reschedule (review may be required)'},{value:'INSTRUCTIONS',label:'Instructions only'}],'AVAILABLE')}${note('A note for your rider','instructions',buyerDetails.delivery_instructions||'')}<div id="schedule-fields" hidden>${field('Reschedule start · Yangon','start','','datetime-local')}${field('Reschedule end · Yangon','end','','datetime-local')}</div>${submit('Save response')}</form></section><p class="customer-order-reference">Order #${esc(buyerCard.order_reference)}</p><p class="customer-footer">A little care goes a long way.<br>Your details are shared only with the delivery team.</p>`;
}

async function load(){
  const g=++generation;page=location.hash.replace(/^#\/?/,'')||'admin';clearTimeout(undoTimer);document.querySelector('dialog')?.remove();current=null;linkURL='';
  shell('<p>Loading API data…</p>',true);
  try{
    if(page.startsWith('track/')){
      const token=tokenFrom(page.slice(6));api.openBuyer(buyerBase,token);buyerCard=await api.buyer.card();buyerDetails=null;
      history.replaceState(null,'',location.pathname+'#/customer');page='customer';
    }
    if(page==='customer'){if(g===generation)shell(customerView());return;}
    const side=page==='rider'?'rider':'admin';
    if(!api.connections[side]){shell(connection(side));return;}
    routes=await api.all(side,'/api/routes');
    if(side==='admin'){
      riders=await api.all('admin','/api/riders');
      if(page.startsWith('order/')){
        const orderId=page.slice(6),loadedOrder=await api.order(orderId);
        const loadedRequests=await api.all('admin',`/api/orders/${orderId}/buyer-requests`);
        let loadedHistory=[],loadedError='';
        try{loadedHistory=await api.all('admin',`/api/orders/${orderId}/events`);}
        catch{loadedError='Delivery history could not be loaded. Refresh to retry; the saved order is unchanged.';}
        if(g!==generation)return;
        current=loadedOrder;requests=loadedRequests;eventHistory=loadedHistory;historyError=loadedError;
      }else orders=await api.all('admin','/api/orders');
    }else{const data=await api.call('rider',`/api/riders/${api.connections.rider.actor.id}/queue`);queue=data.items;}
    if(g===generation)shell(side==='rider'?riderView():current?orderView():adminView());
  }catch(error){if(g===generation){shell('<h1>API data unavailable</h1>'+button('Retry / refresh','refresh')+button('Reconnect','disconnect',page==='rider'?'rider':'admin'));message(errorText(error),true);}}
}
async function run(work,refresh=true){
  if(locked)return;locked=true;const g=generation;
  const buttons=[...document.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
  try{const text=await work();if(g!==generation)return;if(refresh){notice=typeof text==='string'?text:'Saved in the backend database.';await load();}else if(text)message(text);}
  catch(error){if(g===generation)message(errorText(error),true);}
  finally{locked=false;buttons.forEach(b=>b.disabled=false);}
}
function dialog(title,body,handler,label='Confirm'){
  document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.className='functional-dialog';d.innerHTML=`<div class="api-main"><h2>${esc(title)}</h2><form>${body}<p class="error" role="alert" hidden></p><button type="button" class="btn" data-cancel>Cancel</button>${submit(label)}</form></div>`;document.body.append(d);d.showModal();
  d.querySelector('[data-cancel]').onclick=()=>d.close();d.onclose=()=>{d.remove();};
  const form=d.querySelector('form');form.onsubmit=async e=>{e.preventDefault();if(locked)return;locked=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{const text=await handler(new FormData(form));d.close();notice=typeof text==='string'?text:'Saved in backend database.';await load();}catch(error){const el=d.querySelector('[role="alert"]');el.hidden=false;el.textContent=errorText(error);}finally{locked=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);}};return d;
}
function bindForm(id,handler,refresh=true){const f=document.querySelector('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();return run(()=>handler(new FormData(f),f),refresh);};}
function wire(){
  // In-page navigation is presentation state, never a new API workspace route.
  document.querySelectorAll('a[data-section]').forEach(link=>link.onclick=e=>{const target=document.querySelector('#'+link.dataset.section);if(target){e.preventDefault();target.scrollIntoView?.({behavior:'smooth',block:'start'});}});
  bindForm('connect-form',async(data,form)=>{await api.connect(form.dataset.side,String(data.get('base')||'').trim(),String(data.get('actor_id')||'').trim());return 'Connected to the server-bound actor.';});
  bindForm('create-form',async data=>{const row=await api.create(Object.fromEntries(data));orders.unshift(row);notice='Order created. Generate its customer link after reviewing fields.';location.hash='#/order/'+row.id;},false);
  const payment=document.querySelector('[name="payment"]');if(payment)payment.onchange=()=>{if(payment.value==='prepaid')document.querySelector('[name="cod_amount"]').value='0';};
  bindForm('parse-form',async(data)=>{
    const result=await api.call('admin','/api/orders/parse',json({raw_text:data.get('raw')})),form=document.querySelector('#create-form'),a=result.address;
    for(const [name,key]of Object.entries({customer_name:'customer_name',customer_phone:'phone_number',township:'township',street:'street',landmark:'landmark',floor:'building_floor_unit',cod_amount:'cod_amount',delivery_instructions:'delivery_instructions'})){
      const input=form.querySelector(`[name="${name}"]`);input.value=a[key]==null?'':String(a[key]);
    }
    form.querySelector('[name="payment"]').value=a.cod_amount!=null&&Number(a.cod_amount)===0?'prepaid':'cod';
    document.querySelector('#parse-result').textContent=`${result.confidence} · AI: ${result.ai?.status||'not requested'}\n${result.validation_reasons.map(r=>r.message).join('\n')}`;
    return 'Parsed only. Review the fields, then Create order to save.';
  },false);
  bindForm('new-route-form',data=>api.call('admin','/api/routes',json(Object.fromEntries(data))));
  bindForm('new-rider-form',data=>api.call('admin','/api/riders',json({name:data.get('name'),operational_status:'AVAILABLE'})));
  bindForm('edit-api-form',async data=>{const fields=Object.fromEntries(data);fields.cod_amount=mmk(fields.cod_amount);for(const key of Object.keys(fields))if(fields[key]==='')fields[key]=null;await api.patch(current,fields);return 'Fields saved and validation rerun. Refresh customer link if phone changed.';});
  bindForm('ready-form',data=>api.ready(current,data.has('ack')));
  let preparationRetry=null;
  bindForm('prepare-assignment-form',async data=>{
    const selection=data.get('selection'),options={received:data.has('received'),acknowledge:data.has('ack')};
    const fingerprint=JSON.stringify([current.id,current.version,selection,options]);
    if(preparationRetry?.fingerprint!==fingerprint)preparationRetry={fingerprint,id:crypto.randomUUID()};
    const result=await api.prepareAssignment(current,selection,options,preparationRetry.id);
    return `Parcel prepared and assigned to route ${result.route.id.slice(0,8)}. Confirm physical departure here when the rider is ready.`;
  });
  bindForm('open-buyer-form',async data=>{buyerBase=data.get('base');api.openBuyer(buyerBase,data.get('link'));buyerCard=await api.buyer.card();buyerDetails=null;shell(customerView());},false);
  bindForm('verify-api-form',async data=>{await api.buyer.verify(data.get('digits'));buyerDetails=await api.buyer.details();shell(customerView());},false);
  bindForm('buyer-location-form',async data=>{const result=await api.buyer.location({request_id:crypto.randomUUID(),latitude:data.get('latitude'),longitude:data.get('longitude'),initial_pin_acknowledged:data.has('initial_pin_acknowledged')});return result.decision==='REVIEW_REQUIRED'?'Location submitted — awaiting admin review. It is not yet applied to dispatch.':'Delivery point saved.';},false);
  bindForm('buyer-response-form',async data=>{const body={request_id:crypto.randomUUID(),action:data.get('action')};if(data.get('instructions')?.trim())body.instructions=data.get('instructions').trim();if(body.action==='RESCHEDULE'){if(!data.get('start')||!data.get('end'))throw Error('Choose reschedule start and end.');body.time_window={start:data.get('start')+':00+06:30',end:data.get('end')+':00+06:30'};}const result=await api.buyer.respond(body);return result.decision==='REVIEW_REQUIRED'?'Response submitted — admin review is required.':'Customer response saved.';},false);
  const response=document.querySelector('[name="action"]');if(response)response.onchange=()=>document.querySelector('#schedule-fields').hidden=response.value!=='RESCHEDULE';
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action,b.dataset.id));
}
async function handle(action,id){
  if(locked)return;
  const route=routes.find(r=>r.id===id);
  if(action==='save-raw')return run(async()=>{
    const raw_text=document.querySelector('#parse-form [name="raw"]').value;
    const item=document.querySelector('#create-form [name="item"]').value.trim();
    const delivery_day=document.querySelector('#create-form [name="delivery_day"]').value;
    if(!item||!raw_text.trim())throw Error('Enter a parcel description and original chat message.');
    const row=await api.call('admin','/api/orders',json({raw_text,parcel:{item,delivery_day,hub_received:false}}));
    location.hash='#/order/'+row.id;return 'Original chat saved with actual parser provenance.';
  },false);
  if(action==='refresh')return load();
  if(action==='disconnect'){api.disconnect(id);buyerDetails=null;return load();}
  if(action==='receive'||action==='return')return run(async()=>api.operation(current?.id===id?current:await api.order(id),action==='receive'?'RECEIVE':'RETURN_RECEIVED'));
  if(['incident','resolve-incident','resolve-difference'].includes(action))return dialog('Record review reason',note('Reason','reason'),data=>api.operation(current,{'incident':'INCIDENT','resolve-incident':'RESOLVE_INCIDENT','resolve-difference':'RESOLVE_DIFFERENCE'}[action],data.get('reason')));
  if(action==='unassign')return run(()=>api.call('admin',`/api/orders/${id}/unassign`,json({expected_version:current.version})));
  if(action==='link')return run(async()=>{if(current.status==='DRAFT')current=await api.status(current,'NEEDS_REVIEW');const link=await api.call('admin',`/api/orders/${id}/confirmation-link`,json({}));const token=tokenFrom(link.confirmation_url);linkURL=location.href.split('#')[0]+'#/track/'+token;shell(orderView());return 'Private customer link created. Share it only in the customer’s trusted conversation.';},false);
  if(action==='review')return dialog('Review customer request',choice('Decision','decision',['APPROVE','REJECT'],'APPROVE')+note('Evidence / reason (at least 5 characters)','reason'),data=>api.call('admin',`/api/orders/${current.id}/buyer-requests/${id}`,{method:'PATCH',body:{expected_version:current.version,decision:data.get('decision'),reason:data.get('reason')}}));
  if(action==='dispatch')return dialog('Confirm physical departure','<p>All assigned parcels are physically present and the rider is ready to leave.</p>',()=>api.routeAction('admin',route,'DISPATCH'));
  if(action==='handover')return run(async()=>{await api.routeAction('rider',route,'HANDOVER',{amount:route.recorded_total,recorded_total:route.recorded_total});return 'Handover submitted. Next: admin counts physical cash and receives & closes this route.';});
  if(action==='close-route')return run(()=>api.routeAction('admin',route,'CLOSE'));
  if(action==='receipt'||action==='different'){
    const receiving=action==='receipt';const d=dialog(receiving?'Receive cash & close route':'Hand over a different amount',`<p>Recorded ${money(route.recorded_total)}${route.handover?' · Rider declared '+money(route.handover.declared):''}. ${receiving?'Count the physical cash before confirming.':''}</p>${field(receiving?'Cash physically received':'Cash handed over','amount',receiving?'':route.recorded_total,'number','min="0" step="1" required')}<div id="difference-controls">${note('Difference reason','reason')}${receiving?check('Difference investigated and resolved','resolve'):''}</div>`,async data=>{
      const amount=Number(mmk(data.get('amount')));const result=await api.routeAction(receiving?'admin':'rider',route,receiving?'RECEIVE_CLOSE':'HANDOVER',{amount,recorded_total:route.recorded_total,reason:data.get('reason')||null,resolve:data.has('resolve')});
      return result.state==='closed'?'Cash received and route closed.':receiving?'Receipt saved. Route remains open until cash differences and listed issues are resolved.':'Handover submitted — awaiting hub receipt.';
    },receiving?'Confirm receipt & close':'Submit handover');
    const input=d.querySelector('[name="amount"]'),controls=d.querySelector('#difference-controls');input.oninput=()=>{controls.hidden=input.value===''||Number(input.value)===route.recorded_total&&(!receiving||Number(input.value)===route.handover.declared);};input.oninput();return;
  }
  if(action==='deliver'){
    let canSave=false;
    const o=queue.find(o=>o.order_id===id);const d=dialog('Record actual cash & delivery',`<p>Expected ${money(o.cod_amount)}. Confirm the parcel was handed to the recipient.</p>${field('Actual cash collected (MMK)','amount',o.cod_amount,'number','required min="0" step="1"')}${note('Reason if different from expected','reason')}<p id="undo-copy">You can cancel before saving. Save unlocks after two seconds.</p>`,data=>{if(!canSave)throw Error('Wait two seconds before saving this delivery.');return api.delivery(o,'DELIVERED',{actual_amount:Number(mmk(data.get('amount'))),difference_reason:data.get('reason')||null,cod_collected:true});},'Save delivery & cash');
    const save=d.querySelector('[type="submit"]');save.disabled=true;undoTimer=setTimeout(()=>{if(d.open){canSave=true;save.disabled=false;d.querySelector('#undo-copy').textContent='Ready to save. Cancel leaves the delivery incomplete.';}},2000);return;
  }
  if(action==='failed')return dialog('Delivery unsuccessful',choice('Reason','failure_reason',['CUSTOMER_UNAVAILABLE','ADDRESS_NOT_FOUND','CUSTOMER_REFUSED','ACCESS_BLOCKED','COD_NOT_COLLECTED','OTHER'],'CUSTOMER_UNAVAILABLE')+note('Notes','failure_note')+'<p>This parcel must be physically returned to the hub before route closeout. Later retries require a reviewed new plan.</p>',data=>api.delivery(queue.find(o=>o.order_id===id),'FAILED',{failure_reason:data.get('failure_reason'),...(data.get('failure_note')?.trim()?{failure_note:data.get('failure_note').trim()}:{})}));
  if(action==='gps'){
    if(!navigator.geolocation){message('GPS unavailable; enter coordinates manually.',true);return;}
    const form=document.querySelector('#buyer-location-form');navigator.geolocation.getCurrentPosition(p=>{if(document.querySelector('#buyer-location-form')!==form)return;form.querySelector('[name="latitude"]').value=p.coords.latitude.toFixed(7);form.querySelector('[name="longitude"]').value=p.coords.longitude.toFixed(7);form.querySelector('[name="longitude"]').dispatchEvent(new Event('change'));},()=>message('GPS permission denied or unavailable. Enter coordinates manually.',true),{timeout:10000});
  }
}
window.addEventListener('hashchange',()=>{api.buyer?.clear();buyerCard=null;buyerDetails=null;load();});
// Do not register a service worker or persist tokens/private API responses.
if(location.pathname.startsWith('/confirm/')){
  const token=tokenFrom(location.pathname);history.replaceState(null,'','/api.html#/track/'+token);
}
load();
